import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DdOM6S6U.js";const v=JSON.parse('{"title":"View Composers","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview","sidebarGroupTitle":"View Composers"},"headers":[],"relativePath":"system-reference/backend/http/view-composers/overview.md","filePath":"system-reference/backend/http/view-composers/overview.md","lastUpdated":1778363927000}'),r={name:"system-reference/backend/http/view-composers/overview.md"},i=a('<h1 id="view-composers" tabindex="-1">View Composers <a class="header-anchor" href="#view-composers" aria-label="Permalink to &quot;View Composers&quot;">​</a></h1><p><strong>Directory</strong>: <code>src/Http/ViewComposers/</code></p><p>View composers are classes that bind data to every view (or Inertia response) before it is rendered. Modularous registers them automatically in <code>BaseServiceProvider</code>. They inject cross-cutting data — the authenticated user, active navigation state, upload configuration, locale settings, and common URLs — so controllers never have to pass this data manually.</p><h2 id="composers" tabindex="-1">Composers <a class="header-anchor" href="#composers" aria-label="Permalink to &quot;Composers&quot;">​</a></h2><table><thead><tr><th>Composer</th><th>Variable injected</th><th>Description</th></tr></thead><tbody><tr><td><a href="./active-navigation">ActiveNavigation</a></td><td><code>_global_active_navigation</code>, <code>_primary_active_navigation</code>, <code>_secondary_active_navigation</code></td><td>Parses the current route name into navigation depth markers</td></tr><tr><td><a href="./current-user">CurrentUser</a></td><td><code>currentUser</code></td><td>Injects the authenticated user profile using Modularous auth guard</td></tr><tr><td><a href="./files-uploader-config">FilesUploaderConfig</a></td><td><code>filesUploaderConfig</code></td><td>Builds the file-library upload configuration object (endpoint, CSRF, ACL, limits)</td></tr><tr><td><a href="./localization">Localization</a></td><td><code>modularousLocalization</code></td><td>Injects the full locale/language configuration for frontend i18n</td></tr><tr><td><a href="./medias-uploader-config">MediasUploaderConfig</a></td><td><code>mediasUploaderConfig</code></td><td>Builds the media-library upload configuration object (endpoint, CSRF, ACL, limits)</td></tr><tr><td><a href="./urls">Urls</a></td><td><code>urls</code></td><td>Injects commonly used admin route URLs (profile show/update)</td></tr></tbody></table><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p>All composers are bound in <code>BaseServiceProvider::registerViewComposers()</code>. They run on every request that renders a view, so the injected variables are always available in Blade templates and Inertia shared props without any controller boilerplate.</p>',7),s=[i];function d(n,c,l,p,h,u){return o(),t("div",null,s)}const f=e(r,[["render",d]]);export{v as __pageData,f as default};
